async function confirm(text) {
  message(text, { sticky: true });
  const r = await menu(['YES', 'NO'], { x: 170, y: 64 });
  clearSticky();
  return r === 0;
}

function clearSticky() {
  for (let i = stack.length - 1; i >= 0; i--) if (stack[i].sticky) stack.splice(i, 1);
}
